  "check_code": "from pathlib import Path\nimport sqlite3\n\n\nTARGET = \"RI-20250831-000884\"\nPAYMENT_ORDER = \"PO-20250903-CL936-001\"\nLEDGER_ORDER = \"PAY-CLM-202508-01938\"\nBANK_TRACE = \"CMB202509041430778191\"\n\n\ndef _db(workspace):\n    root = Path(workspace).resolve()\n    candidates = [root.parent / \"system\" / \"yonyou_claim_accounting\" / \"state.db\", root / \"system\" / \"yonyou_claim_accounting\" / \"state.db\"]\n    for path in candidates:\n        if path.exists():\n            return path\n    raise FileNotFoundError(\"找不到 yonyou_claim_accounting/state.db\")\n\n\ndef check_reconciliation_post_state(workspace):\n    with sqlite3.connect(_db(workspace)) as con:\n        con.row_factory = sqlite3.Row\n        row = con.execute(\"SELECT recon_status, difference_yuan, difference_reason FROM reconciliation_items WHERE recon_item_id = ?\", (TARGET,)).fetchone()\n    if row is None:\n        return {\"score\": 0, \"detail\": \"目标对账项不存在\"}\n    reason = str(row[\"difference_reason\"] or \"\")\n    ok = row[\"recon_status\"] == \"EXCEPTION\" and abs(float(row[\"difference_yuan\"]) - 0) <= 1e-6 and all(token in reason for token in (PAYMENT_ORDER, LEDGER_ORDER, BANK_TRACE))\n    return {\"score\": 1 if ok else 0, \"detail\": {\"status\": row[\"recon_status\"], \"difference_yuan\": row[\"difference_yuan\"], \"reason\": reason}}\n\n\ndef check_other_reconciliation_rows_untouched(workspace):\n    protected = {\n        \"RI-20250902-000091\": (\"EXCEPTION\", -500),\n        \"RI-20250902-MIG-004\": (\"MIGRATED\", 4860),\n        \"RI-20250527-583912\": (\"EXCEPTION\", 1200),\n    }\n    with sqlite3.connect(_db(workspace)) as con:\n        count = con.execute(\"SELECT COUNT(*) FROM reconciliation_items\").fetchone()[0]\n        rows = con.execute(\"SELECT recon_item_id, recon_status, difference_yuan FROM reconciliation_items WHERE recon_item_id IN (?,?,?)\", tuple(protected)).fetchall()\n    actual = {row[0]: (row[1], float(row[2])) for row in rows}\n    ok = count == 145 and all(key in actual and actual[key][0] == state and abs(actual[key][1] - amount) <= 1e-6 for key, (state, amount) in protected.items())\n    return {\"score\": 1 if ok else 0, \"detail\": {\"row_count\": count, \"protected\": actual}}\n",
